function patchV4Helper(s,newPluginSha){return replaceOnce(s,EXPECTED[FILES.plugin],newPluginSha,'v4_plugin_sha')}
function syntax(name,content,esm=false){const tmp='/tmp/prhm-v12-'+name+'-'+process.pid+(esm?'.mjs':'.js');try{fs.writeFileSync(tmp,content,{mode:0o600});exec('/usr/local/bin/prhm-node',['--check',tmp])}finally{try{fs.unlinkSync(tmp)}catch{}}}
function unixHealth(sock,version){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','--unix-socket',sock,'http://localhost/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true&&(!version||x.version===version))return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('unix_health_not_ready:'+sock)}
function loopHealth(port){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','http://127.0.0.1:'+port+'/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true)return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('loop_health_not_ready:'+port)}
function atomic(file,data,mode){const tmp=file+'.v12-'+process.pid+'.tmp';fs.writeFileSync(tmp,data,{mode});fs.chmodSync(tmp,mode);fs.renameSync(tmp,file)}
function candidate(){const o={base:fs.readFileSync(FILES.base,'utf8'),executor:fs.readFileSync(FILES.executor,'utf8'),plugin:fs.readFileSync(FILES.plugin,'utf8'),policy:fs.readFileSync(FILES.policy,'utf8'),v4helper:fs.readFileSync(FILES.v4helper,'utf8')};const c={base:patchBase(o.base),executor:patchExecutor(o.executor),plugin:patchPlugin(o.plugin),policy:patchPolicy(o.policy),v4helper:null,helper:Buffer.from(HELPER_B64,'base64')};const pluginSha=shaBuf(Buffer.from(c.plugin));c.v4helper=patchV4Helper(o.v4helper,pluginSha);return {o,c,pluginSha}}
